Here is the commit message:
usb: gadget: f_tcm: Fix NULL pointer dereferences in nexus
 handling

The `tpg->tpg_nexus` pointer in the USB Target driver is dynamically
managed and tied to userspace configuration via ConfigFS. It can be
NULL if the USB host sends requests before the nexus is fully
established or immediately after it is dropped.

Currently, functions like `bot_submit_command()` and the data
transfer paths retrieve `tv_nexus = tpg->tpg_nexus` and immediately
dereference `tv_nexus->tvn_se_sess` without any validation. If a
malicious or misconfigured USB host sends a BOT (Bulk-Only Transport)
command during this race window, it triggers a NULL pointer
dereference, leading to a kernel panic (local DoS).

This exposes an inconsistent API usage within the module, as peer
functions like `usbg_submit_command()` and `bot_send_bad_response()`
correctly implement a NULL check for `tv_nexus` before proceeding.

Fix this by bringing consistency to the nexus handling. Add the
missing `if (!tv_nexus)` checks to the vulnerable BOT command and
request processing paths, aborting the command gracefully with an
error instead of crashing the system.

Fixes: c52661d60f63 ("usb-gadget: Initial merge of target module for UASP + BOT")
Cc: stable <stable@kernel.org>
Signed-off-by: Jiasheng Jiang <jiashengjiangcool@gmail.com>
Reviewed-by: Thinh Nguyen <Thinh.Nguyen@synopsys.com>
Link: https://patch.msgid.link/20260219023834.17976-1-jiashengjiangcool@gmail.com
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug is a NULL pointer dereference occurring when the USB gadget target module's `tpg->tpg_nexus` pointer is NULL. This pointer, dynamically managed via ConfigFS, can be NULL if the USB host sends BOT (Bulk-Only Transport) commands before the nexus is established or after it is dropped. Functions such as `bot_submit_command()` and `bot_cmd_work()` retrieve `tv_nexus = tpg->tpg_nexus` but then directly dereference `tv_nexus->tvn_se_sess` or other members without a NULL check, leading to a kernel panic during the race window. The commit adds missing NULL checks in `usbg_submit_cmd()` and `bot_cmd_work()` to gracefully handle this condition.

Here is the patch:

 static void usbg_submit_cmd(struct usbg_cmd *cmd)
 {
 	struct se_cmd *se_cmd;
 	struct tcm_usbg_nexus *tv_nexus;
 	struct usbg_tpg *tpg;
 	int dir, flags = (TARGET_SCF_UNKNOWN_SIZE | TARGET_SCF_ACK_KREF);

 	/*
 	 * Note: each command will spawn its own process, and each stage of the
 	 * command is processed sequentially. Should this no longer be the case,
 	 * locking is needed.
 	 */
 	if (cmd->flags & USBG_CMD_PENDING_DATA_WRITE) {
 		target_execute_cmd(&cmd->se_cmd);
 		cmd->flags &= ~USBG_CMD_PENDING_DATA_WRITE;
 		return;
 	}

 	se_cmd = &cmd->se_cmd;
 	tpg = cmd->fu->tpg;
 	tv_nexus = tpg->tpg_nexus;
+	if (!tv_nexus) {
+		struct usb_gadget *gadget = fuas_to_gadget(cmd->fu);
+
+		dev_err(&gadget->dev, "Missing nexus, ignoring command\n");
+		return;
+	}
+
 	dir = get_cmd_dir(cmd->cmd_buf);
 	if (dir < 0)
 		goto out;

 	target_submit_cmd(se_cmd, tv_nexus->tvn_se_sess, cmd->cmd_buf,
 			  cmd->sense_iu.sense, cmd->unpacked_lun, cmd->data_len,
 			  cmd->prio_attr, dir, flags);

 	return;

 out:
 	__target_init_cmd(se_cmd,
 			  tv_nexus->tvn_se_sess->se_tpg->se_tpg_tfo,
 			  tv_nexus->tvn_se_sess, cmd->data_len, DMA_NONE,
 			  cmd->prio_attr, cmd->sense_iu.sense,
 			  cmd->unpacked_lun, NULL);
 	transport_send_check_condition_and_sense(se_cmd,
 			TCM_UNSUPPORTED_SCSI_OPCODE, 0);
 }


 static void bot_cmd_work(struct work_struct *work)
 {
 	struct usbg_cmd *cmd = container_of(work, struct usbg_cmd, work);
 	struct se_cmd *se_cmd;
 	struct tcm_usbg_nexus *tv_nexus;
 	struct usbg_tpg *tpg;
 	int flags = TARGET_SCF_ACK_KREF;
 	int dir;

 	/*
 	 * Note: each command will spawn its own process, and each stage of the
 	 * command is processed sequentially. Should this no longer be the case,
 	 * locking is needed.
 	 */
 	if (cmd->flags & USBG_CMD_PENDING_DATA_WRITE) {
 		target_execute_cmd(&cmd->se_cmd);
 		cmd->flags &= ~USBG_CMD_PENDING_DATA_WRITE;
 		return;
 	}

 	se_cmd = &cmd->se_cmd;
 	tpg = cmd->fu->tpg;
 	tv_nexus = tpg->tpg_nexus;
+	if (!tv_nexus) {
+		struct usb_gadget *gadget = fuas_to_gadget(cmd->fu);
+
+		dev_err(&gadget->dev, "Missing nexus, ignoring command\n");
+		return;
+	}
+
 	dir = get_cmd_dir(cmd->cmd_buf);
 	if (dir < 0)
 		goto out;

 	target_submit_cmd(se_cmd, tv_nexus->tvn_se_sess,
 			  cmd->cmd_buf, cmd->sense_iu.sense, cmd->unpacked_lun,
 			  cmd->data_len, cmd->prio_attr, dir, flags);
 	return;

 out:
 	__target_init_cmd(se_cmd,
 			  tv_nexus->tvn_se_sess->se_tpg->se_tpg_tfo,
 			  tv_nexus->tvn_se_sess, cmd->data_len, DMA_NONE,
 			  cmd->prio_attr, cmd->sense_iu.sense,
 			  cmd->unpacked_lun, NULL);
 	transport_send_check_condition_and_sense(se_cmd,
 				TCM_UNSUPPORTED_SCSI_OPCODE, 0);
 }



